CREATE TABLE IF NOT EXISTS student_responses (id TEXT PRIMARY KEY, student_alias TEXT NOT NULL, class_group TEXT NOT NULL DEFAULT '', site_lot_id TEXT NOT NULL DEFAULT 'lotA', house_title TEXT NOT NULL DEFAULT '', house_concept TEXT NOT NULL DEFAULT '', house_config_json TEXT NOT NULL, inquiry_question TEXT NOT NULL DEFAULT '', line_summary_json TEXT NOT NULL DEFAULT '', plane_summary_json TEXT NOT NULL DEFAULT '', relation_summary_json TEXT NOT NULL DEFAULT '', reflection_note TEXT NOT NULL DEFAULT '', self_eval_json TEXT NOT NULL DEFAULT '', is_public INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_student_responses_public_created ON student_responses (is_public, created_at DESC);
CREATE TABLE IF NOT EXISTS exhibition_comments (id TEXT PRIMARY KEY, response_id TEXT NOT NULL, author_alias TEXT NOT NULL, feedback_type TEXT NOT NULL DEFAULT 'vector-relation', content TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_exhibition_comments_response_created ON exhibition_comments (response_id, created_at ASC);
CREATE TABLE IF NOT EXISTS ethics_notes (id TEXT PRIMARY KEY, author_alias TEXT NOT NULL, stance TEXT NOT NULL, argument TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_ethics_notes_created ON ethics_notes (created_at DESC);
